public class FileInfoSerializer : XmlSerializer
{
    public override void WriteXml(XmlWriter writer, object obj)
    {
        FileInfo fileInfo = (FileInfo)obj;
        writer.WriteStartElement("File");
        writer.WriteValue(fileInfo.File);
        writer.WriteEndElement();

        writer.WriteStartElement("CreationDate");
        writer.WriteValue(fileInfo.CreationDate.ToString("s"));
