    {
        var file = reader.ReadElementContentAsString();
        var creationDate = DateTime.Parse(reader.ReadElementContentAsString());

        return new FileInfo
        {
            File = file,
            CreationDate = creationDate
        };
    }
}

public static class FileUtils
{
    public static DateTime GetFileCreationDate(string filePath)
    {
        try
