            FileInfo fileInfo = new FileInfo(filePath);
            FileInfoSerializer serializer = new FileInfoSerializer();
            string xml = serializer.Serialize(fileInfo);
            FileInfo deserializedFileInfo = (FileInfo)serializer.Deserialize(new StringReader(xml));
            return deserializedFileInfo.CreationDate;
        }
